        if (day % 2 == 0) {
            day -= 1;
        }
    } else if (dayStep == 3) {
        if (day % 3 == 0) {
            day -= 2;
        } else if (day % 3 == 1) {
            day -= 1;
        }
    } else if (dayStep == 4) {
        if (day % 4 == 0) {
            day -= 3;
        } else if (day % 4 == 1) {
            day -= 2;
